#!/usr/bin/env node
// VSIX smoke test for every table format the VSIX declares, then the PDF editor, in ONE disposable profile.
//
// Usage (repo root):  node test/vsix_smoke/tables.mjs <path-to.vsix> [--fixtures dir] [--pdf file.pdf] [--keep]
// Fixtures: sample.<ext> files (3 rows: alpha/beta/gamma). Default: generated by make_table_fixtures.py with
//   `conda run -n myproject python` (override the interpreter command with DFV_FIXTURE_PYTHON="python3").
// For each customEditors filename pattern of the form *.<ext> a fixture is opened with `code -r` and must render
// the data (grid cells containing "gamma" for table-shaped files). Then sample.pdf must still open in
// dataFileViewer.pdf, and the extension-host logs must hold no extension error. Patterns that are not plain
// extensions (e.g. kdb's **/*_kdb/*) are reported SKIP. Exit code: 0 if no FAIL.
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import { spawn, execFileSync } from 'node:child_process';
import net from 'node:net';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import { activationLog, codeCli, descendants, isElectronHelper, samplePdf, vscodeExecutable, vsixManifest } from './helpers.mjs';

const require = createRequire(import.meta.url);
const { chromium } = require('playwright');
const args = process.argv.slice(2);
const flag = n => args.includes(n);
const opt = n => { const i = args.indexOf(n); return i < 0 ? undefined : args[i + 1]; };
const vsix = path.resolve(args.find((a, i) => !a.startsWith('--') && !['--pdf', '--fixtures'].includes(args[i - 1]) ) ?? '');
const timeout = +(process.env.DFV_SMOKE_TIMEOUT_MS || 60000);
const sleep = ms => new Promise(r => setTimeout(r, ms));
const results = [];
const report = (name, status, note = '') => { results.push({ name, status, note }); console.log(`${status.padEnd(4)} ${name}${note ? ' - ' + note : ''}`); };

async function main() {
  const manifest = vsixManifest(vsix);
  const editors = manifest.contributes?.customEditors ?? [];
  const extId = `${manifest.publisher}.${manifest.name}`;
  const exe = vscodeExecutable();
  const root = await fs.mkdtemp('/tmp/dfvt-');
  const user = path.join(root, 'user'), exts = path.join(root, 'extensions'), ws = path.join(root, 'ws');
  await fs.mkdir(path.join(user, 'User'), { recursive: true }); await fs.mkdir(ws);
  // Fixtures (copied into the workspace: the originals are never opened).
  let fx = opt('--fixtures');
  if (!fx) {
    fx = path.join(root, 'fixtures');
    const py = (process.env.DFV_FIXTURE_PYTHON || 'conda run -n myproject python').split(' ');
    execFileSync(py[0], [...py.slice(1), fileURLToPath(new URL('./make_table_fixtures.py', import.meta.url)), fx], { stdio: 'pipe' });
  }
  // Every declared pattern; *.pdf is covered by the PDF step, the rest by a table fixture.
  // MAT has its own catalog/array UI and installed-host gate, rather than the SQL table grid.
  const patterns = [...new Set(editors.filter(e => !['dataFileViewer.pdf', 'dataFileViewer.mat'].includes(e.viewType)).flatMap(e => e.selector.map(s => s.filenamePattern)))];
  const hasPdf = editors.some(e => e.viewType === 'dataFileViewer.pdf');
  const csv = path.join(ws, 'sample.csv');
  await fs.writeFile(csv, 'id,name,score\n1,alpha,10.5\n2,beta,20.25\n3,gamma,30\n');
  const pdf = path.join(ws, 'sample.pdf'); samplePdf(pdf, opt('--pdf'));
  const assoc = { ...(hasPdf ? { '*.pdf': 'dataFileViewer.pdf' } : {}) };
  for (const e of editors) if (e.priority === 'option' && e.viewType !== 'dataFileViewer.pdf') for (const s of e.selector) assoc[s.filenamePattern] = e.viewType; // option-priority editors need an explicit choice
  await fs.writeFile(path.join(user, 'User', 'settings.json'), JSON.stringify({
    'workbench.startupEditor': 'none', 'security.workspace.trust.enabled': false, 'extensions.autoUpdate': false,
    'extensions.ignoreRecommendations': true, 'update.mode': 'none', 'telemetry.telemetryLevel': 'off', 'workbench.editorAssociations': assoc,
  }));
  const profileArgs = ['--user-data-dir', user, '--extensions-dir', exts];
  const env = { ...process.env }; delete env.ELECTRON_RUN_AS_NODE;
  let child, browser;
  const stop = () => { if (child?.pid) try { process.kill(-child.pid, 'SIGKILL'); } catch {} };
  const deadline = setTimeout(() => { stop(); console.error('Table smoke exceeded its deadline.'); process.exit(1); }, timeout * (patterns.length + 3) + 60000);
  try {
    execFileSync(codeCli(), [...profileArgs, '--install-extension', vsix, '--force'], { stdio: 'pipe', timeout: 60000 });
    const listed = execFileSync(codeCli(), [...profileArgs, '--list-extensions', '--show-versions']).toString();
    assert.ok(listed.toLowerCase().includes(`${extId}@${manifest.version}`.toLowerCase()), `installed ${extId}@${manifest.version}`);
    report('install', 'PASS', `${extId}@${manifest.version}`);
    const probe = net.createServer(); await new Promise(r => probe.listen(0, '127.0.0.1', r));
    const port = probe.address().port; await new Promise(r => probe.close(r));
    child = spawn(exe, [...profileArgs, `--remote-debugging-port=${port}`, '--disable-gpu', '--disable-workspace-trust',
      '--disable-extension', 'GitHub.copilot-chat', '--skip-welcome', '--skip-release-notes', '--disable-telemetry', '--new-window', ws],
    { env, detached: true, stdio: 'ignore' });
    for (let i = 0; i < 120 && !browser; i++) {
      try { browser = await chromium.connectOverCDP(`http://127.0.0.1:${port}`, { timeout: 1000 }); } catch { await sleep(250); }
    }
    assert.ok(browser, 'VS Code debugging endpoint');
    const page = () => browser.contexts()[0]?.pages().at(-1);
    const webviewFrames = () => (page()?.frames() ?? []).filter(f => f.url().includes('vscode-webview'));
    const waitFor = async (what, fn, ms = timeout) => { for (const end = Date.now() + ms; Date.now() < end;) { const v = await fn().catch(() => undefined); if (v) return v; await sleep(250); } throw new Error(`timed out: ${what}`); };
    await waitFor('workbench', async () => page()?.locator('.monaco-workbench').count());
    await sleep(2000);

    const seen = new Set();
    const open = async file => { // returns the new webview frame once the tab exists
      const known = new Set(webviewFrames().map(f => f.url()));
      execFileSync(codeCli(), [...profileArgs, '-r', file], { stdio: 'pipe', timeout: 30000 });
      return known;
    };
    const tables = [{ name: 'csv', file: csv, pattern: '*.csv' }];
    for (const p of patterns) {
      if (p === '**/*_kdb/*') {
        const folder = path.join(ws, 'sample_kdb'); await fs.mkdir(folder);
        const file = path.join(folder, 'sample.kdb');
        await fs.copyFile(fileURLToPath(new URL('../../native/crates/kdb/tests/corpus/single_row.kdb', import.meta.url)), file);
        tables.push({ name: 'kdb', file, pattern: p, expected: 'only', minCells: 2 });
        continue;
      }
      const m = p.match(/^\*\.(\w+)$/);
      if (!m) { report(p, 'SKIP', 'not a plain extension pattern; needs a directory layout'); continue; }
      if (m[1] === 'csv') continue;
      const src = path.join(fx, `sample.${m[1]}`);
      if (!await fs.stat(src).catch(() => null)) { report(m[1], 'FAIL', `no fixture ${src}`); continue; }
      const dst = path.join(ws, `sample.${m[1]}`); await fs.copyFile(src, dst);
      tables.push({ name: m[1], file: dst, pattern: p });
    }
    for (const t of tables) {
      const before = await fs.readFile(t.file), expected = t.expected ?? 'gamma';
      const known = await open(t.file);
      try {
        const frame = await waitFor(`${t.name} grid`, async () => {
          for (const f of webviewFrames()) {
            if (known.has(f.url()) || seen.has(f.url())) continue;
            const cells = await f.locator('td[data-r]').count();
            if (cells >= (t.minCells ?? 3) && (await f.locator('body').innerText()).includes(expected)) return f;
          }
        });
        seen.add(frame.url());
        const tab = await page().locator('.tab').filter({ hasText: path.basename(t.file) }).count();
        report(t.name, tab ? 'PASS' : 'FAIL', `${await frame.locator('td[data-r]').count()} cells incl. "${expected}"${tab ? '' : '; tab missing'}`);
      } catch (e) {
        const texts = [];
        for (const f of webviewFrames()) if (!known.has(f.url()) && !seen.has(f.url())) texts.push((await f.locator('body').innerText().catch(() => '')).replace(/\s+/g, ' ').slice(0, 160));
        report(t.name, 'FAIL', `${String(e.message).split('\n')[0]}; new webview text: ${JSON.stringify(texts)}`);
      }
      assert.deepEqual(await fs.readFile(t.file), before, `${t.name}: viewing preserves source bytes`);
      // The native supervisor admits eight workers; close each format before opening the next.
      const currentTab = page().locator('.tab').filter({ hasText: path.basename(t.file) }).first();
      await currentTab.click();
      await page().keyboard.press(process.platform === 'darwin' ? 'Meta+W' : 'Control+W');
      await waitFor(`${t.name} tab closed`, async () => !await page().locator('.tab').filter({ hasText: path.basename(t.file) }).count());
      await waitFor('table worker released on close', async () => !descendants(child.pid).some(p => /\/dfv-table(?:\.exe)?(?:\s|$)/.test(p.command)));
    }

    // The PDF editor must still work in the same profile after all table editors were activated.
    if (hasPdf) {
      const before = new Set(descendants(child.pid).map(p => p.pid));
      const known = await open(pdf);
      try {
        const pdfFrame = await waitFor('PDF webview', async () => {
          for (const f of webviewFrames()) if (!known.has(f.url()) && !seen.has(f.url()) && (await f.locator('body *').count()) > 5) return f;
        });
        const tab = await page().locator('.tab[aria-label*="sample.pdf"]').count();
        report('pdf editor after tables', tab ? 'PASS' : 'FAIL', `${await pdfFrame.locator('canvas, img, svg').count()} canvas/img/svg`);
        const worker = await waitFor('PDF worker', async () => descendants(child.pid).find(p => !before.has(p.pid) && !isElectronHelper(p.command)));
        report('pdf worker after tables', 'PASS', worker.command.slice(0, 100));
      } catch (e) { report('pdf editor after tables', 'FAIL', String(e.message).split('\n')[0]); }
    }

    // Extension-host log: activation succeeded and no error line mentions the extension.
    const act = activationLog(user, extId);
    report('extension activates', act.activated ? 'PASS' : 'FAIL', act.error ?? '');
    const logs = [];
    const walk = async d => { for (const e of await fs.readdir(d, { withFileTypes: true }).catch(() => [])) { const p = path.join(d, e.name); if (e.isDirectory()) await walk(p); else if (/\.log$/.test(e.name)) logs.push(p); } };
    await walk(path.join(user, 'logs'));
    const bad = [];
    for (const p of logs) { // an error's stack names the extension a few lines below the [error] line
      const ls = (await fs.readFile(p, 'utf8')).split('\n');
      ls.forEach((l, i) => { if (/\[error\]|\bUncaught\b/i.test(l) && /data-file-viewer|dataFileViewer|pdf/i.test(ls.slice(i, i + 4).join('\n'))) bad.push(`${path.basename(p)}: ${l.slice(0, 200)}`); });
    }
    report('no extension errors in logs', bad.length ? 'FAIL' : 'PASS', bad.slice(0, 3).join(' | '));
  } catch (e) {
    const act = activationLog(user, extId);
    if (act.error) console.error(act.error.slice(0, 300));
    report('smoke', 'FAIL', String(e?.message ?? e).split('\n')[0]);
  } finally {
    stop(); await browser?.close().catch(() => {});
    if (flag('--keep')) console.log(`kept ${root}`); else await fs.rm(root, { recursive: true, force: true, maxRetries: 20, retryDelay: 100 });
    clearTimeout(deadline);
  }
  process.exitCode = results.some(r => r.status === 'FAIL') ? 1 : 0;
}
main();
